/* @autogenerated */
import { OFFLINE_FILE_PREFIX, OfflineOp } from './offline.model';

/**
 * Claves de las que depende un valor: las de sus referencias (`$ref`, a cualquier profundidad) y los ids de los
 * adjuntos locales (`offline-file://…`).
 */
export function collectRefs(value: any, found: Set<string> = new Set()): string[] {
  if (typeof value === 'string') {
    if (value.startsWith(OFFLINE_FILE_PREFIX)) {
      found.add(value.substring(OFFLINE_FILE_PREFIX.length));
    }
  } else if (Array.isArray(value)) {
    value.forEach((item) => collectRefs(item, found));
  } else if (value && typeof value === 'object' && !(value instanceof Date) && !(value instanceof Blob)) {
    Object.entries(value).forEach(([field, inner]) => {
      if (field === '$ref' && typeof inner === 'string') {
        found.add(inner);
      } else {
        collectRefs(inner, found);
      }
    });
  }
  return [...found];
}

/** Copia de `value` con cada string `from` sustituido por `to`, a cualquier profundidad. */
export function replaceValue(value: any, from: string, to: string): any {
  if (value === from) {
    return to;
  }
  if (Array.isArray(value)) {
    return value.map((item) => replaceValue(item, from, to));
  }
  if (value && typeof value === 'object' && !(value instanceof Date) && !(value instanceof Blob)) {
    const copy: Record<string, any> = {};
    Object.entries(value).forEach(([field, inner]) => (copy[field] = replaceValue(inner, from, to)));
    return copy;
  }
  return value;
}

/** Identidad de una entidad entre repositorios. */
export function entityId(op: Pick<OfflineOp, 'repo' | 'key'>): string {
  return op.repo + '|' + op.key;
}

/**
 * Operaciones que dependen de las de `roots`, directa o indirectamente, por orden de `seq`: las posteriores sobre la
 * misma entidad y las que referencian algo que creaba una operación ya afectada (un alta o un adjunto). Devuelve el
 * `seq` de cada dependiente con el `seq` de la raíz que lo bloquea.
 */
export function dependentsOf(ops: OfflineOp[], roots: OfflineOp[]): Map<number, number> {
  const entities = new Map<string, number>();
  const created = new Map<string, number>();
  const mark = (op: OfflineOp, root: number) => {
    entities.set(entityId(op), root);
    if (op.kind === 'add' || op.kind === 'file') {
      created.set(op.key, root);
    }
  };
  roots.forEach((root) => mark(root, root.seq!));
  const rootSeqs = new Set(roots.map((root) => root.seq));
  const firstRoot = Math.min(...roots.map((root) => root.seq!));
  const result = new Map<number, number>();
  sorted(ops)
    .filter((op) => op.seq! > firstRoot && !rootSeqs.has(op.seq))
    .forEach((op) => {
      const bySelf = entities.get(entityId(op));
      const byRef = collectRefs(op.payload)
        .map((ref) => created.get(ref))
        .find((seq) => seq !== undefined);
      const root = bySelf ?? byRef;
      if (root !== undefined) {
        result.set(op.seq!, root);
        mark(op, root);
      }
    });
  return result;
}

/** Operaciones por orden de llegada. */
export function sorted(ops: OfflineOp[]): OfflineOp[] {
  return [...ops].sort((a, b) => a.seq! - b.seq!);
}

/** Cambios en la cola para añadir una operación. */
export interface CompactPlan {
  /** Operación nueva que se añade al final (sin `seq`). */
  append?: OfflineOp;
  /** Operaciones existentes que se reescriben. */
  replace: OfflineOp[];
  /** `seq` de las operaciones que se eliminan. */
  remove: number[];
}

/**
 * Añade `op` a la cola fusionándola, si se puede, con la última operación pendiente de la misma entidad:
 * - un `update` o un `patch` sobre un alta pendiente se aplican al alta;
 * - un `update` sustituye al `update`/`patch` anterior; un `patch` se mezcla con el anterior;
 * - un `delete` elimina las operaciones pendientes de la entidad y, si la entidad se creó sin conexión, no sube nada.
 *
 * No se fusiona si el cambio referencia algo que se creó después de la operación con la que se fusionaría: subiría
 * antes que lo que necesita.
 */
export function compact(queue: OfflineOp[], op: OfflineOp): CompactPlan {
  const same = sorted(queue).filter((item) => item.kind !== 'file' && entityId(item) === entityId(op));
  const last = same[same.length - 1];
  if (op.kind === 'add' || op.kind === 'file' || !last || last.kind === 'delete') {
    return { append: op, replace: [], remove: [] };
  }
  if (op.kind === 'delete') {
    const createdOffline = same.some((item) => item.kind === 'add');
    return {
      append: createdOffline ? undefined : { ...op, base: same[0].base ?? op.base },
      replace: [],
      remove: same.map((item) => item.seq!),
    };
  }
  const refs = new Set(collectRefs(op.payload));
  const later = queue.some((item) => item.seq! > last.seq! && refs.has(item.key));
  if (later || op.path || last.path) {
    return { append: { ...op, base: last.base ?? op.base }, replace: [], remove: [] };
  }
  const payload = op.kind === 'update' ? op.payload : { ...(last.payload ?? {}), ...(op.payload ?? {}) };
  // Un update completo sustituye a un patch: la operación pasa a ser un update
  const kind = last.kind === 'patch' && op.kind === 'update' ? 'update' : last.kind;
  return {
    replace: [{ ...last, kind, payload, label: op.label ?? last.label, status: 'pending', error: undefined }],
    remove: [],
  };
}

/** Filtros que no restringen el contenido: paginación, orden y cursores. */
const NON_FILTERS = ['limit', 'order', 'sort', 'cursor', 'since', 'page', 'size', 'offset'];

/**
 * Si `item` cumple `query`, para mostrar en los listados las altas hechas sin conexión. Se evalúa a partir de los
 * nombres: `campo` compara por igualdad (o con el `$ref`), `campos` (plural) con alguno de la lista, `<clave>s` con la
 * clave y `search` busca el texto en los campos de texto. Un filtro que no se sabe evaluar excluye el elemento.
 */
export function matchesQuery(item: any, query: any, key: string): boolean {
  if (!item || !query) {
    return !!item;
  }
  return Object.entries(query).every(([name, wanted]) => {
    if (NON_FILTERS.includes(name) || wanted === undefined || wanted === null || wanted === '') {
      return true;
    }
    if (name === 'search') {
      const text = String(wanted).toLowerCase();
      return Object.values(item).some((value) => typeof value === 'string' && value.toLowerCase().includes(text));
    }
    if (name in item) {
      return equalsValue(item[name], wanted);
    }
    const single = name.endsWith('s') ? name.substring(0, name.length - 1) : null;
    const field = single === key ? key : single && single in item ? single : null;
    if (!field) {
      return false;
    }
    const options = Array.isArray(wanted) ? wanted : String(wanted).split(',');
    return options.some((option) => equalsValue(item[field], option));
  });
}

function equalsValue(value: any, wanted: any): boolean {
  const plain = (v: any) => (v && typeof v === 'object' && '$ref' in v ? v.$ref : v);
  if (Array.isArray(wanted)) {
    return wanted.some((option) => equalsValue(value, option));
  }
  return String(plain(value)) === String(plain(wanted));
}
